'use strict';
const content=document.getElementById('content'),platform=document.getElementById('platform'),surface=document.getElementById('play-surface'),frame=document.getElementById('game-frame');
const session={visited:false,loaded:false,points:0,rounds:[],claims:new Set(),finished:new Set()};let page='games',filter='全部';
const catalog=[{id:'minesweeper',name:'金币扫雷',category:'益智',duration:'约 3 分钟',cover:'sweep-cover',art:'',available:true},{id:'2048',name:'2048',category:'益智',duration:'合并数字',cover:'cover-2048',art:'<span class="cover-number">2048</span>'},{id:'memory',name:'记忆翻牌',category:'益智',duration:'配对挑战',cover:'cover-memory',art:'<span aria-hidden="true">▣ ▣</span>'},{id:'rhythm',name:'节奏点击',category:'反应',duration:'节奏挑战',cover:'cover-rhythm',art:'<span aria-hidden="true">ϟ</span>'}];
function showPage(next){page=['games','rewards','me'].includes(next)?next:'games';platform.hidden=false;surface.hidden=true;if(session.loaded)frame.contentWindow.postMessage({type:'platform-pause',paused:true},location.origin);document.querySelectorAll('.navigation button').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});render();window.scrollTo(0,0)}
function render(){if(page==='games'){const games=catalog.filter(g=>filter==='全部'||g.category===filter);content.innerHTML=`<div class="welcome"><div><h1>今天，玩点什么？</h1><p class="muted">轻松开局，随时来一局。</p></div><span class="session-chip">无需连接钱包 · 免费试玩</span></div>${session.visited?'<div class="continue"><div class="continue-symbol" aria-hidden="true">◈</div><div><h2>金币扫雷</h2><p class="muted">最近玩过</p></div><button class="primary" data-play>回到游戏</button></div>':''}<div class="section-row"><h2>探索游戏</h2><div class="filters" aria-label="游戏分类">${['全部','益智','反应'].map(c=>`<button class="filter" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div></div><div class="catalog">${games.map(g=>`<button class="game-card" ${g.available?'data-play':'disabled'} aria-label="${g.name}${g.available?'，开始游戏':'，即将上线'}"><div class="cover ${g.cover}">${g.available?'<span class="game-label">现在就玩</span>':''}${g.art}</div><div class="game-details"><div class="game-title-row"><h2>${g.name}</h2></div><p>${g.duration}</p><div class="card-bottom"><span class="tag">${g.category}</span><span class="${g.available?'play-label':'coming'}">${g.available?'开始游戏 ↗':'即将上线'}</span></div></div></button>`).join('')}</div><p class="catalog-footer">更多游戏正在筹备中</p>`}else if(page==='rewards'){content.innerHTML=`<h1>我的奖励</h1><p class="muted">游戏积分与链上资产，分别查看。</p><div class="panel-grid"><section class="panel"><h2>本次体验积分</h2><div class="balance">${session.points}<span>积分</span></div><p class="muted">扫雷通关后可领取 440 模拟积分。</p></section><section class="panel"><h2>链上资产</h2><div class="empty">尚未接入钱包</div><p class="muted">当前版本没有充值、提现或真实交易。</p></section></div><section class="panel list-panel"><h2>领取记录</h2>${session.rounds.some(r=>r.claimed)?session.rounds.filter(r=>r.claimed).map(r=>`<div class="record"><div>金币扫雷 · 通关奖励<small>${r.time}</small></div><span class="positive">+440 积分</span></div>`).join(''):'<div class="empty">还没有领取记录。完成一局扫雷，收下你的第一份奖励。</div><button class="primary" data-play>去玩扫雷</button>'}</section><p class="notice">积分仅用于本次 Demo 体验，刷新页面后清空，不具有货币价值。</p>`}else{content.innerHTML=`<h1>我的</h1><div class="profile"><span class="avatar">P</span><div><h2>游客玩家</h2><p class="muted">先玩一局，轻松探索</p></div></div><div class="panel-grid"><section class="panel"><h2>本次游戏记录</h2>${session.rounds.length?session.rounds.slice().reverse().map(r=>`<div class="record"><div>金币扫雷<small>${r.time} · ${r.seconds} 秒</small></div><span class="${r.won?'positive':'muted'}">${r.won?'已通关':'踩到地雷'}</span></div>`).join(''):'<div class="empty">还没有完成的游戏。</div><button class="primary" data-play>开始第一局</button>'}</section><section><div class="rows"><button class="row-button" data-help="account"><span>账户与钱包</span><span>未接入 ›</span></button><button class="row-button" data-help="rules"><span>玩法说明</span><span>扫雷 ›</span></button><button class="row-button" data-help="about"><span>关于 PLAYROOM</span><span>Demo ›</span></button></div><p class="notice">游戏记录仅保留在本次页面会话中。</p></section></div>`}}
function play(){session.visited=true;platform.hidden=true;surface.hidden=false;if(!session.loaded){frame.src='minesweeper.html';session.loaded=true}else frame.contentWindow.postMessage({type:'platform-pause',paused:false},location.origin);window.scrollTo(0,0)}
function help(kind){const copy={account:['账户与钱包','当前使用游客模式，无需注册即可试玩。\n账户绑定和钱包连接尚未接入。'],rules:['金币扫雷怎么玩？','金币上的数字表示周围 8 格中的地雷数量。\n揭开全部 44 个安全方块即可通关；用插旗模式或鼠标右键标记疑似地雷。\n首次点击安全。通关后可领取 440 模拟积分。'],about:['关于 PLAYROOM','一个轻量休闲游戏平台 Demo。\n当前可玩：金币扫雷。其他游戏正在筹备中。\n所有奖励均为模拟积分，不涉及真实资产。']};document.getElementById('help-title').textContent=copy[kind][0];document.getElementById('help-text').textContent=copy[kind][1];document.getElementById('help').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-play'))play();else if(b.dataset.page){location.hash=b.dataset.page;showPage(b.dataset.page)}else if(b.dataset.filter){filter=b.dataset.filter;render()}else if(b.dataset.help)help(b.dataset.help)});
for(const id of ['help-close','help-ok'])document.getElementById(id).onclick=()=>document.getElementById('help').close();window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow||!e.data||typeof e.data!=='object')return;const d=e.data;if(d.type==='game-return'){showPage('games')}else if(d.type==='game-finished'&&typeof d.roundId==='string'&&!session.finished.has(d.roundId)&&typeof d.won==='boolean'&&Number.isInteger(d.seconds)&&d.seconds>=0){session.finished.add(d.roundId);session.rounds.push({id:d.roundId,won:d.won,seconds:d.seconds,claimed:false,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})})}else if(d.type==='game-reward'&&typeof d.roundId==='string'&&!session.claims.has(d.roundId)){const round=session.rounds.find(r=>r.id===d.roundId&&r.won);if(!round)return;session.claims.add(d.roundId);round.claimed=true;session.points+=440}if(!platform.hidden)render()});
showPage(location.hash.slice(1));
